/**
 * Minecraft Java Edition LCG Random (java.util.Random clone)
 * Required for exact seed derivation.
 */
class Java_Random{
    constructor(seed){
        this.set_seed(seed);
    }
    set_seed(seed){
        const masked = (BigInt(seed) ^ 0x5DEECE66Dn) & 0xFFFFFFFFFFFFn;
        this.seed = (masked * 0x5DEECE66Dn + 0xBn) & 0xFFFFFFFFFFFFn;
    }
    
    next(bits){
        this.seed = (this.seed * 0x5DEECE66Dn + 0xBn) & 0xFFFFFFFFFFFFn;
        return Number(this.seed >> (48n - BigInt(bits)));
    }
    /** return value is in range from 0 to bound-1; */
    next_int(bound){
        let r = this.next(31);
        let m = bound - 1;
        // the condition is only true if bound is a power of 2;
        if((bound & m) === 0){
            r = Number((BigInt(bound) * BigInt(r)) >> 31n);
        }
        else{
            let u = r;
            // this looks like it ensures perfect uniformity;
            // though maybe it does some other weird thing;
            // though any other idea sounds completely useless to me;
            while(u - (r = u % bound) + m < 0){
                u = this.next(31);
            }
        }
        return r;
    }
    /** return value is in range from 0 to 1-2**-53; */
    next_double(){
        const high = BigInt(this.next(26));
        const low = BigInt(this.next(27));
        return Number((high << 27n) + low) / 9007199254740992.0;
    }
}

